    ["Subtle"] = "İnce",
    ["Support report saved: {path}"] = "Destek raporu kaydedildi: {path}",
    ["TALK TO {character}"] = "KONUŞ: {character}",
    ["TEXT  >"] = "METİN  >",
    ["Talk to companions in any language: each character answers in the language you use. It uses a multilingual copy of each character, so what they remember from these conversations is kept apart from your English ones; forgetting a character clears both. Pocket TTS speaks only English, so turning this on switches Companion voices to OmniVoice · Balanced when the optional OmniVoice pack is installed, or to Convai · Cloud voice otherwise; without the pack, Natural speech and Expressive emotions are turned off, because the cloud voice would read their tags aloud. Off by default."] = "Yoldaşlarla istediğin dilde konuş: her karakter, kullandığın dilde yanıt verir. Her karakterin çok dilli bir kopyasını kullanır; bu yüzden bu konuşmalardan hatırladıkları, İngilizce konuşmalarından ayrı tutulur. Bir karakteri unutmak ikisini de siler. Pocket TTS yalnızca İngilizce konuşur; bu yüzden bunu açmak, isteğe bağlı OmniVoice paketi kuruluysa Yoldaş seslerini OmniVoice · Dengeli olarak, değilse Convai · Bulut sesi olarak değiştirir; paket yoksa bulut sesi etiketleri yüksek sesle okuyacağı için Doğal konuşma ve İfadeli duygular kapatılır. Varsayılan olarak kapalı.",
    ["Pocket TTS speaks only English. Turn off Multilingual conversations to choose it."] = "Pocket TTS yalnızca İngilizce konuşur. Seçmek için Çok dilli konuşmaları kapat.",
    ["Multilingual conversations needs a voice that speaks every language, so {setting} was switched to {voice}."] = "Çok dilli konuşmalar her dili konuşan bir ses gerektirir, bu yüzden {setting} ayarı {voice} olarak değiştirildi.",
    ["Natural speech and Expressive emotions need the OmniVoice pack while Multilingual conversations is on: the Convai cloud voice would read their tags aloud."] = "Çok dilli konuşmalar açıkken Doğal konuşma ve İfadeli duygular OmniVoice paketini gerektirir: Convai bulut sesi etiketleri yüksek sesle okurdu.",
    ["Natural speech and Expressive emotions were turned off: the Convai cloud voice would read their tags aloud. With the OmniVoice pack, all three work together."] = "Doğal konuşma ve İfadeli duygular kapatıldı: Convai bulut sesi etiketleri yüksek sesle okurdu. OmniVoice paketiyle üçü birlikte çalışır.",
    ["That character model is unavailable."] = "Bu karakter modeli kullanılamıyor.",
